import raw from "@/data/elk-hunt-areas.json";
import { DemandDraw, MapArea, PointsDraw, RegionDraws, Season, neighborsIn, seasonDates } from "@/lib/hunts";
import { elkAreaHarvest, elkLicenseHarvest, elkRegionHarvest } from "@/lib/harvest";
import type { License } from "@/lib/license";

// Generated by scripts/hunts/build_hunt_data.py from WGFD's draw reports,
// Chapter 7 (elk seasons and boundaries) and the elk hunt-area layer.
// Server-only: the file is ~400 KB with geometry, so pages pass the slices
// they need to client components, never this module.

export interface ElkHunt {
  type: string;
  description: string;
  cowCalf: boolean;
  seasons: Season[];
  nrPoints?: PointsDraw;
  nrSpecialPoints?: PointsDraw;
  nrRandom?: DemandDraw;
  nrSpecialRandom?: DemandDraw;
  nrCowCalf?: DemandDraw;
  resident?: DemandDraw;
  residentCowCalf?: DemandDraw;
}

export interface ElkArea extends MapArea {
  herdUnit: number;
  herdName: string;
  region: string; // nonresident general-license region: "Eastern", "Southern" or "Western"
  sqMiles: number;
  hunts: ElkHunt[];
  general: Season[]; // general-license seasons, youth-only weekends last; empty in limited-quota-only areas
  closed: boolean;
  boundary: string | null;
}

interface ElkData {
  year: number;
  sources: { odds: string; boundaries: string; seasons: string };
  nrRegions: Record<string, RegionDraws>;
  areas: ElkArea[];
}

const data = raw as unknown as ElkData;

export const ELK_YEAR = data.year;
export const ELK_SOURCES = data.sources;
export const ELK_AREAS = data.areas;

export const elkSlug = (a: Pick<ElkArea, "area">) => `area-${a.area}`;
export const elkPath = (a: Pick<ElkArea, "area">) => `/hunting/elk/${elkSlug(a)}`;

export function getElkArea(slug: string): ElkArea | undefined {
  const m = /^area-(\d+)$/.exec(slug);
  return m ? ELK_AREAS.find((a) => a.area === Number(m[1])) : undefined;
}

// The headline hunt for an area: the first "any elk" type, else the first hunt.
export function mainHunt(a: ElkArea): ElkHunt | undefined {
  return a.hunts.find((h) => !h.cowCalf && /any elk/i.test(h.description)) ?? a.hunts[0];
}

export const neighbors = (a: ElkArea) => neighborsIn(ELK_AREAS, a);

// The draw for the nonresident general license an area's general seasons take.
// The draw reports key regions by initial ("W"); the boundary layer spells them out.
export const regionDraws = (a: ElkArea): RegionDraws | undefined => data.nrRegions[a.region[0]];

const pad = (n: number) => String(n).padStart(3, "0");

// What a nonresident can apply for to hunt an area: the region's general
// license where the area has a general season, then its limited-quota types,
// the main hunt first. Success on the general license is the area's general
// hunters, residents included; the finder uses the region's nonresidents.
export function elkLicenses(a: ElkArea): License[] {
  const d = regionDraws(a);
  const harvest = elkAreaHarvest(a.area);
  const general: License[] =
    a.general.length && d && (d.nrPoints || d.nrRandom)
      ? [
          {
            id: "general",
            kicker: `${a.region} region`,
            title: "General license",
            serial: `E-${a.region[0]}-GEN`,
            points: d.nrPoints,
            random: d.nrRandom,
            demand: d.nrPoints ? undefined : d.nrRandom,
            note: seasonDates(a.general[0]),
            harvest: elkLicenseHarvest(harvest?.types.GEN),
          },
        ]
      : [];
  const main = mainHunt(a);
  const hunts = [...a.hunts]
    .sort((x, y) => (x === main ? -1 : y === main ? 1 : 0))
    .map((h) => ({
      id: `type-${h.type}`,
      kicker: `Type ${h.type}`,
      title: h.description,
      serial: `E-${pad(a.area)}-${h.type}`,
      points: h.nrPoints,
      random: h.nrRandom,
      demand: h.nrCowCalf ?? (h.nrPoints ? undefined : h.nrRandom),
      resident: h.resident ?? h.residentCowCalf,
      note: h.seasons[0] ? seasonDates(h.seasons[0]) : undefined,
      harvest: elkLicenseHarvest(harvest?.types[h.type]),
    }));
  return [...general, ...hunts];
}

// A nonresident region general license on its own, for the hunt finder.
export function elkRegionLicense(region: string): License | undefined {
  const d = data.nrRegions[region[0]];
  if (!d || !(d.nrPoints || d.nrRandom)) return undefined;
  return {
    id: "general",
    kicker: `${region} region`,
    title: "General license",
    serial: `E-${region[0]}-GEN`,
    points: d.nrPoints,
    random: d.nrRandom,
    demand: d.nrPoints ? undefined : d.nrRandom,
    harvest: elkLicenseHarvest(elkRegionHarvest(region)),
  };
}

export const ELK_REGIONS = Array.from(new Set(ELK_AREAS.map((a) => a.region))).sort();
